SELECT , s.name AS student_name, s.student_no AS student_no, u.real_name AS counselor_name FROM student_record e LEFT JOIN student s ON e.student_id = s.id LEFT JOIN sys_user u ON e.counselor_id = u.id
e.record_type = 'EMPLOYMENT' AND s.name LIKE CONCAT('%', #{studentName}, '%') AND e.status = #{employmentStatus} AND e.student_id = #{studentId} AND e.counselor_id = #{counselorId}
ORDER BY CASE WHEN e.status = '未就业' THEN 0 ELSE 1 END, e.occur_date DESC, e.id DESC

