UPDATE student_record
student_id = #{studentId}, status = #{employmentStatus}, company = #{company}, position = #{position}, salary = #{salary}, city = #{city}, school = #{school}, major = #{major}, occur_date = #{trackDate}, remark = #{remark}, counselor_id = #{counselorId},
WHERE record_type = 'EMPLOYMENT' AND id = #{id}
